{"command":"python3 -c "
import subprocess, json

type_map = {}
for i in range(1, 300):
    res = subprocess.run(['./executable', 'google.com', '-t', str(i), '@10.0.0.2', '-J'], capture_output=True, text=True)
    if res.returncode == 0:
        try:
            data = json.loads(res.stdout)
            qtype = data['responses'][0]['queries'][0]['type']
            type_map[i] = qtype
        except Exception:
            pass

for k, v in sorted(type_map.items()):
    print(f'{k:3d} -> {v!r}')
""}

