            "  --seconds                Do not format durations, display them as seconds\n",
            "  --time                   Print how long the response took to arrive\n\n",
            "Meta options:\n",
            "  -?, --help               Print list of command-line options\n",
            "  -v, --version            Print version information\n"
        ));
    }
}

pub fn print_version(color: bool) {
    if color {
        print!(concat!(
            "dog \x1b[1;32m●\x1b[0m command-line DNS client\n",
            "v0.2.0-pre [d436ea3b] built on 2026-06-11 \x1b[1;31m(pre-release!)\x1b[0m\n",
            "\x1b[1;4;34mhttps://dns.lookup.dog/\x1b[0m\n"
        ));
    } else {
        print!(concat!(
            "dog ● command-line DNS client\n",
            "v0.2.0-pre [d436ea3b] built on 2026-06-11 (pre-release!)\n",
            "mhttps://dns.lookup.dog/\n"
        ));
    }
}

pub fn parse_args() -> ParseResult {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        return ParseResult::Help;
    }

    let mut domains = Vec::new();
    let mut record_types = Vec::new();
    let mut nameservers = Vec::new();
    let mut classes = Vec::new();
    let mut edns = EdnsSetting::Hide;
    let mut txid = None;
    let mut tweaks = ProtocolTweaks::default();
    let mut transports = Vec::new();
    let mut short = false;
    let mut json = false;
    let mut color = ColorMode::Automatic;
    let mut seconds = false;
    let mut time = false;

    let mut i = 0;
    let mut parse_options = true;

    while i < args.len() {
        let arg = &args[i];

        if parse_options && arg == "--" {
            parse_options = false;
            i += 1;
            continue;
        }

        if parse_options && arg.starts_with("--") {
            let key_val: Vec<&str> = arg[2..].splitn(2, '=').collect();
            let key = key_val[0];
            let val_in_arg = if key_val.len() > 1 { Some(key_val[1]) } else { None };

            match key {
                "help" => return ParseResult::Help,
                "version" => return ParseResult::Version,
                "short" => short = true,
                "json" => json = true,
                "seconds" => seconds = true,
                "time" => time = true,
                "udp" => transports.push(TransportType::Udp),
                "tcp" => transports.push(TransportType::Tcp),
                "tls" => transports.push(TransportType::Tls),
                "https" => transports.push(TransportType::Https),
                "query" => {
                    let val = match val_in_arg {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                &args[i]
                            } else {
                                return ParseResult::Error("dog: Invalid options: Argument to option 'query' missing".to_string());
                            }
                        }
                    };
                    domains.push(val.to_string());
                }
                "type" => {
                    let val = match val_in_arg {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                &args[i]
                            } else {
                                return ParseResult::Error("dog: Invalid options: Argument to option 'type' missing".to_string());
                            }
                        }
                    };
                    match type_str_to_num(val) {
                        Some(num) => record_types.push(num),
                        None => return ParseResult::Error(format!("dog: Invalid options: Invalid query type \"{}\"", val)),
                    }
                }
                "nameserver" => {
                    let val = match val_in_arg {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                &args[i]
                            } else {
                                return ParseResult::Error("dog: Invalid options: Argument to option 'nameserver' missing".to_string());
                            }
                        }
                    };
                    nameservers.push(val.to_string());
                }
                "class" => {
                    let val = match val_in_arg {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                &args[i]
                            } else {
                                return ParseResult::Error("dog: Invalid options: Argument to option 'class' missing".to_string());
                            }
                        }
                    };
                    match class_str_to_num(val) {
                        Some(num) => classes.push(num),
                        None => return ParseResult::Error(format!("dog: Invalid options: Invalid query class \"{}\"", val)),
                    }
                }
                "edns" => {
                    let val = match val_in_arg {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                &args[i]
                            } else {
                                return ParseResult::Error("dog: Invalid options: Argument to option 'edns' missing".to_string());
                            }
                        }
                    };
                    match val.to_lowercase().as_str() {
                        "show" => edns = EdnsSetting::Show,
                        "hide" => edns = EdnsSetting::Hide,
                        "disable" | "off" => edns = EdnsSetting::Disable,
                        _ => return ParseResult::Error(format!("dog: Invalid options: Invalid EDNS setting \"{}\"", val)),
                    }
                }
                "txid" => {
                    let val = match val_in_arg {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                &args[i]
                            } else {
                                return ParseResult::Error("dog: Invalid options: Argument to option 'txid' missing".to_string());
                            }
                        }
                    };
                    match val.parse::<u16>() {
                        Ok(num) => txid = Some(num),
                        Err(_) => return ParseResult::Error(format!("dog: Invalid options: Invalid transaction ID \"{}\"", val)),
                    }
                }
                "color" | "colour" => {
                    let val = match val_in_arg {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                &args[i]
                            } else {
                                return ParseResult::Error("dog: Invalid options: Argument to option 'color' missing".to_string());
                            }
                        }
                    };
                    match val.to_lowercase().as_str() {
                        "always" => color = ColorMode::Always,
                        "never" => color = ColorMode::Never,
                        _ => color = ColorMode::Automatic,
                    }
                }
                _ => return ParseResult::Error(format!("dog: Invalid options: Unrecognized option: '{}'", key)),
            }
            i += 1;
            continue;
        }

        if parse_options && arg.starts_with('-') && arg.len() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    '?' => return ParseResult::Help,
                    'v' => return ParseResult::Version,
                    '1' => short = true,
                    'J' => json = true,
                    'U' => transports.push(TransportType::Udp),
                    'T' => transports.push(TransportType::Tcp),
                    'S' => transports.push(TransportType::Tls),
                    'H' => transports.push(TransportType::Https),
                    'q' | 't' | 'n' | 'Z' => {
                        let rest_of_arg: String = chars[j+1..].iter().collect();
                        let val = if !rest_of_arg.is_empty() {
                            rest_of_arg
                        } else if i + 1 < args.len() {
                            i += 1;
                            args[i].clone()
                        } else {
                            return ParseResult::Error(format!("dog: Invalid options: Argument to option '{}' missing", c));
                        };

                        match c {
                            'q' => domains.push(val),
                            't' => {
                                match type_str_to_num(&val) {
                                    Some(num) => record_types.push(num),
                                    None => return ParseResult::Error(format!("dog: Invalid options: Invalid query type \"{}\"", val)),
                                }
                            }
                            'n' => nameservers.push(val),
                            'Z' => {
                                if val == "aa" {
                                    tweaks.aa = true;
                                } else if val == "ad" {
                                    tweaks.ad = true;
                                } else if val == "cd" {
                                    tweaks.cd = true;
                                } else if val.starts_with("bufsize=") {
                                    match val["bufsize=".len()..].parse::<u16>() {
                                        Ok(sz) => tweaks.bufsize = Some(sz),
                                        Err(_) => return ParseResult::Error(format!("dog: Invalid options: Invalid protocol tweak \"{}\"", val)),
                                    }
                                } else {
                                    return ParseResult::Error(format!("dog: Invalid options: Invalid protocol tweak \"{}\"", val));
                                }
                            }
                            _ => unreachable!(),
                        }
                        break;
                    }
                    _ => return ParseResult::Error(format!("dog: Invalid options: Unrecognized option: '{}'", c)),
                }
                j += 1;
            }
            i += 1;
            continue;
        }

        // Positional argument
        if arg.starts_with("@https://") || arg.starts_with("@http://") {
            nameservers.push(arg[1..].to_string());
        } else if arg.starts_with('@') {
            nameservers.push(arg[1..].to_string());
        } else if let Some(cls) = class_str_to_num(arg) {
            if arg.eq_ignore_ascii_case("IN") || arg.eq_ignore_ascii_case("CH") || arg.eq_ignore_ascii_case("HS") {
                classes.push(cls);
            } else if let Some(rtype) = type_str_to_num(arg) {
                if !arg.chars().all(|c| c.is_ascii_digit()) {
                    record_types.push(rtype);
                } else {
                    domains.push(arg.clone());
                }
            } else {
                domains.push(arg.clone());
            }
        } else if let Some(rtype) = type_str_to_num(arg) {
            if !arg.chars().all(|c| c.is_ascii_digit()) {
                record_types.push(rtype);
            } else {
                domains.push(arg.clone());
            }
        } else {
            domains.push(arg.clone());
        }

        i += 1;
    }

    if domains.is_empty() {
        return ParseResult::Help;
    }

    ParseResult::Ok(Options {
        domains,
        record_types,
        nameservers,
        classes,
        edns,
        txid,
        tweaks,
        transports,
        short,
        json,
        color,
        seconds,
        time,
    })
}
