pub fn encode_domain(domain: &str) -> Vec<u8> {
    let mut buf = Vec::new();
    let d = domain.trim_end_matches('.');
    if !d.is_empty() {
        for label in d.split('.') {
            buf.push(label.len() as u8);
            buf.extend_from_slice(label.as_bytes());
        }
    }
    buf.push(0);
    buf
}

pub fn build_query(
    txid: u16,
    domain: &str,
    qtype: u16,
    qclass: u16,
    edns: bool,
    udp_payload_size: u16,
    aa: bool,
    ad: bool,
    cd: bool,
) -> Vec<u8> {
    let mut buf = Vec::new();
    buf.extend_from_slice(&txid.to_be_bytes());

    let mut flags: u16 = 0x0100; // Recursion Desired (RD)
    if aa { flags |= 0x0400; }
    if ad { flags |= 0x0020; }
    if cd { flags |= 0x0010; }
    buf.extend_from_slice(&flags.to_be_bytes());

    buf.extend_from_slice(&1u16.to_be_bytes()); // QDCOUNT = 1
    buf.extend_from_slice(&0u16.to_be_bytes()); // ANCOUNT = 0
    buf.extend_from_slice(&0u16.to_be_bytes()); // NSCOUNT = 0
    let arcount: u16 = if edns { 1 } else { 0 };
    buf.extend_from_slice(&arcount.to_be_bytes()); // ARCOUNT

    // Question section
    buf.extend_from_slice(&encode_domain(domain));
    buf.extend_from_slice(&qtype.to_be_bytes());
    buf.extend_from_slice(&qclass.to_be_bytes());

    // EDNS OPT record
    if edns {
        buf.push(0); // Root domain
        buf.extend_from_slice(&41u16.to_be_bytes()); // Type OPT
        buf.extend_from_slice(&udp_payload_size.to_be_bytes()); // CLASS = payload size
        buf.extend_from_slice(&0u32.to_be_bytes()); // TTL = ext rcode + version + flags
        buf.extend_from_slice(&0u16.to_be_bytes()); // RDLEN = 0
    }

    buf
}

pub struct PacketParser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> PacketParser<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self { data, pos: 0 }
    }

    pub fn parse_u8(&mut self) -> Result<u8, String> {
        if self.pos >= self.data.len() {
            return Err("insufficient data".to_string());
        }
        let val = self.data[self.pos];
        self.pos += 1;
        Ok(val)
    }

    pub fn parse_u16(&mut self) -> Result<u16, String> {
        if self.pos + 2 > self.data.len() {
            return Err("insufficient data".to_string());
        }
        let val = u16::from_be_bytes([self.data[self.pos], self.data[self.pos + 1]]);
        self.pos += 2;
        Ok(val)
    }

    pub fn parse_u32(&mut self) -> Result<u32, String> {
        if self.pos + 4 > self.data.len() {
            return Err("insufficient data".to_string());
        }
        let val = u32::from_be_bytes([
            self.data[self.pos],
            self.data[self.pos + 1],
            self.data[self.pos + 2],
            self.data[self.pos + 3],
        ]);
        self.pos += 4;
        Ok(val)
    }

    pub fn parse_bytes(&mut self, len: usize) -> Result<Vec<u8>, String> {
        if self.pos + len > self.data.len() {
            return Err("insufficient data".to_string());
        }
        let val = self.data[self.pos..self.pos + len].to_vec();
        self.pos += len;
        Ok(val)
    }

    pub fn parse_domain(&mut self) -> Result<String, String> {
        let mut labels = Vec::new();
        let mut pos = self.pos;
        let mut jumped = false;
        let mut jumps = 0;

        loop {
            if jumps > 32 {
                return Err("too many domain pointers".to_string());
            }
            if pos >= self.data.len() {
                return Err("insufficient data".to_string());
            }
            let len = self.data[pos];
            if len == 0 {
                if !jumped {
                    self.pos = pos + 1;
                }
                break;
            }

            if (len & 0xC0) == 0xC0 {
                if pos + 2 > self.data.len() {
                    return Err("insufficient data".to_string());
                }
                let ptr = (((len & 0x3F) as usize) << 8) | (self.data[pos + 1] as usize);
                if !jumped {
                    self.pos = pos + 2;
                    jumped = true;
                }
                pos = ptr;
                jumps += 1;
                continue;
            }

            let len = len as usize;
            pos += 1;
            if pos + len > self.data.len() {
                return Err("insufficient data".to_string());
            }
            let label_str = String::from_utf8_lossy(&self.data[pos..pos + len]).to_string();
            labels.push(label_str);
            pos += len;
        }

        if labels.is_empty() {
            Ok(".".to_string())
        } else {
            Ok(labels.join(".") + ".")
        }
    }
}

fn parse_domain_from_slice(data: &[u8], mut pos: usize) -> Result<(String, usize), String> {
    let mut labels = Vec::new();
    let initial_pos = pos;
    let mut jumped = false;
    let mut next_pos = pos;
    let mut jumps = 0;

    loop {
        if jumps > 32 {
            return Err("too many domain pointers".to_string());
        }
        if pos >= data.len() {
            return Err("insufficient data".to_string());
        }
        let len = data[pos];
        if len == 0 {
            if !jumped {
                next_pos = pos + 1;
            }
            break;
        }

        if (len & 0xC0) == 0xC0 {
            if pos + 2 > data.len() {
                return Err("insufficient data".to_string());
            }
            let ptr = (((len & 0x3F) as usize) << 8) | (data[pos + 1] as usize);
            if !jumped {
                next_pos = pos + 2;
                jumped = true;
            }
            pos = ptr;
            jumps += 1;
            continue;
        }

        let len = len as usize;
        pos += 1;
        if pos + len > data.len() {
            return Err("insufficient data".to_string());
        }
        let label_str = String::from_utf8_lossy(&data[pos..pos + len]).to_string();
        labels.push(label_str);
        pos += len;
    }

    let domain = if labels.is_empty() {
        ".".to_string()
    } else {
        labels.join(".") + "."
    };

    Ok((domain, if jumped { next_pos } else { pos }))
}

fn parse_len_string(data: &[u8], mut pos: usize) -> Result<(String, usize), String> {
    if pos >= data.len() {
        return Err("insufficient data".to_string());
    }
    let len = data[pos] as usize;
    pos += 1;
    if pos + len > data.len() {
        return Err("insufficient data".to_string());
    }
    let s = String::from_utf8_lossy(&data[pos..pos + len]).to_string();
    Ok((s, pos + len))
}

fn format_loc_precision(val: u8) -> (String, u32) {
    let mantissa = ((val >> 4) & 0x0F) as u32;
    let exponent = (val & 0x0F) as u32;
    let base: u32 = 10;
    let total_cm = mantissa * base.pow(exponent);
    let str_val = format!("{}e{}", mantissa, exponent);
    (str_val, total_cm)
}

fn format_loc_coordinate(val: u32, is_lat: bool) -> String {
    let center: i64 = 2147483648;
    let diff = (val as i64) - center;
    let abs_diff = diff.abs();

    let msec = abs_diff % 1000;
    let total_sec = abs_diff / 1000;
    let sec = total_sec % 60;
    let total_min = total_sec / 60;
    let min = total_min % 60;
    let deg = total_min / 60;

    let dir = if is_lat {
        if diff >= 0 { "N" } else { "S" }
    } else {
        if diff >= 0 { "E" } else { "W" }
    };

    if deg > 90 && is_lat {
        return "Out of range".to_string();
    }
    if deg > 180 && !is_lat {
        return "Out of range".to_string();
    }

    if msec == 0 {
        format!("{}°{}′{}″ {}", deg, min, sec, dir)
    } else {
        format!("{}°{}′{}.{:03}″ {}", deg, min, sec, msec, dir)
    }
}

pub fn parse_packet(data: &[u8]) -> Result<DnsPacket, String> {
    let mut parser = PacketParser::new(data);

    let txid = parser.parse_u16()?;
    let flags = parser.parse_u16()?;
    let qdcount = parser.parse_u16()?;
    let ancount = parser.parse_u16()?;
    let nscount = parser.parse_u16()?;
    let arcount = parser.parse_u16()?;

    let header = DnsHeader {
        txid,
        flags,
        qdcount,
        ancount,
        nscount,
        arcount,
    };

    let mut questions = Vec::new();
    for _ in 0..qdcount {
        let name = parser.parse_domain()?;
        let qtype = parser.parse_u16()?;
        let qclass = parser.parse_u16()?;
        questions.push(DnsQuestion { name, qtype, qclass });
    }

    let parse_record_list = |parser: &mut PacketParser, count: u16| -> Result<Vec<DnsRecord>, String> {
        let mut recs = Vec::new();
        for _ in 0..count {
            let name = parser.parse_domain()?;
            let rtype = parser.parse_u16()?;
            let rclass = parser.parse_u16()?;
            let ttl = parser.parse_u32()?;
            let rdlen = parser.parse_u16()? as usize;
            let rdata_bytes = parser.parse_bytes(rdlen)?;

            let record_data = match rtype {
                1 => { // A
                    if rdata_bytes.len() != 4 {
                        return Err("invalid A record length".to_string());
                    }
                    let ip = format!("{}.{}.{}.{}", rdata_bytes[0], rdata_bytes[1], rdata_bytes[2], rdata_bytes[3]);
                    RecordData::A(ip)
                }
                28 => { // AAAA
                    if rdata_bytes.len() != 16 {
                        return Err("invalid AAAA record length".to_string());
                    }
                    let mut segments = Vec::new();
                    for i in 0..8 {
                        let seg = u16::from_be_bytes([rdata_bytes[i * 2], rdata_bytes[i * 2 + 1]]);
                        segments.push(seg);
                    }
                    // format IPv6
                    let ip = std::net::Ipv6Addr::new(
                        segments[0], segments[1], segments[2], segments[3],
                        segments[4], segments[5], segments[6], segments[7],
                    ).to_string();
                    RecordData::AAAA(ip)
                }
                5 => { // CNAME
                    let (domain, _) = parse_domain_from_slice(data, parser.pos - rdlen)?;
                    RecordData::CNAME(domain)
                }
                12 => { // PTR
                    let (domain, _) = parse_domain_from_slice(data, parser.pos - rdlen)?;
                    RecordData::PTR(domain)
                }
                2 => { // NS
                    let (domain, _) = parse_domain_from_slice(data, parser.pos - rdlen)?;
                    RecordData::NS(domain)
                }
                15 => { // MX
                    if rdata_bytes.len() < 2 {
                        return Err("invalid MX record".to_string());
                    }
                    let preference = u16::from_be_bytes([rdata_bytes[0], rdata_bytes[1]]);
                    let (exchange, _) = parse_domain_from_slice(data, parser.pos - rdlen + 2)?;
                    RecordData::MX { preference, exchange }
                }
                16 => { // TXT
                    let mut txts = Vec::new();
                    let mut p = 0;
                    while p < rdata_bytes.len() {
                        let l = rdata_bytes[p] as usize;
                        p += 1;
                        if p + l > rdata_bytes.len() {
                            break;
                        }
                        let s = String::from_utf8_lossy(&rdata_bytes[p..p + l]).to_string();
                        txts.push(s);
                        p += l;
                    }
                    RecordData::TXT(txts)
                }
                6 => { // SOA
                    let base_pos = parser.pos - rdlen;
                    let (mname, p1) = parse_domain_from_slice(data, base_pos)?;
                    let (rname, p2) = parse_domain_from_slice(data, p1)?;
                    if p2 + 20 > data.len() {
                        return Err("invalid SOA record".to_string());
                    }
                    let serial = u32::from_be_bytes([data[p2], data[p2+1], data[p2+2], data[p2+3]]);
                    let refresh = u32::from_be_bytes([data[p2+4], data[p2+5], data[p2+6], data[p2+7]]);
                    let retry = u32::from_be_bytes([data[p2+8], data[p2+9], data[p2+10], data[p2+11]]);
                    let expire = u32::from_be_bytes([data[p2+12], data[p2+13], data[p2+14], data[p2+15]]);
                    let minimum = u32::from_be_bytes([data[p2+16], data[p2+17], data[p2+18], data[p2+19]]);
                    RecordData::SOA { mname, rname, serial, refresh, retry, expire, minimum }
                }
                33 => { // SRV
                    if rdata_bytes.len() < 6 {
                        return Err("invalid SRV record".to_string());
                    }
                    let priority = u16::from_be_bytes([rdata_bytes[0], rdata_bytes[1]]);
                    let weight = u16::from_be_bytes([rdata_bytes[2], rdata_bytes[3]]);
                    let port = u16::from_be_bytes([rdata_bytes[4], rdata_bytes[5]]);
                    let (target, _) = parse_domain_from_slice(data, parser.pos - rdlen + 6)?;
                    RecordData::SRV { priority, weight, port, target }
                }
                257 => { // CAA
                    if rdata_bytes.len() < 2 {
                        return Err("invalid CAA record".to_string());
                    }
                    let flags = rdata_bytes[0];
                    let critical = (flags & 128) != 0;
                    let tag_len = rdata_bytes[1] as usize;
                    if 2 + tag_len > rdata_bytes.len() {
                        return Err("invalid CAA tag".to_string());
                    }
                    let tag = String::from_utf8_lossy(&rdata_bytes[2..2 + tag_len]).to_string();
                    let value = String::from_utf8_lossy(&rdata_bytes[2 + tag_len..]).to_string();
                    RecordData::CAA { critical, tag, value }
                }
                35 => { // NAPTR
                    let base_pos = parser.pos - rdlen;
                    if rdata_bytes.len() < 4 {
                        return Err("invalid NAPTR record".to_string());
                    }
                    let order = u16::from_be_bytes([rdata_bytes[0], rdata_bytes[1]]);
                    let preference = u16::from_be_bytes([rdata_bytes[2], rdata_bytes[3]]);
                    let (flags, p1) = parse_len_string(data, base_pos + 4)?;
                    let (service, p2) = parse_len_string(data, p1)?;
                    let (regex, p3) = parse_len_string(data, p2)?;
                    let (replacement, _) = parse_domain_from_slice(data, p3)?;
                    RecordData::NAPTR { order, preference, flags, service, regex, replacement }
                }
                52 => { // TLSA
                    if rdata_bytes.len() < 3 {
                        return Err("invalid TLSA record".to_string());
                    }
                    let certificate_usage = rdata_bytes[0];
                    let selector = rdata_bytes[1];
                    let matching_type = rdata_bytes[2];
                    let certificate_data = hex::encode(&rdata_bytes[3..]);
                    RecordData::TLSA { certificate_usage, selector, matching_type, certificate_data }
                }
                44 => { // SSHFP
                    if rdata_bytes.len() < 2 {
                        return Err("invalid SSHFP record".to_string());
                    }
                    let algorithm = rdata_bytes[0];
                    let fingerprint_type = rdata_bytes[1];
                    let fingerprint = hex::encode(&rdata_bytes[2..]);
                    RecordData::SSHFP { algorithm, fingerprint_type, fingerprint }
                }
                13 => { // HINFO
                    let base_pos = parser.pos - rdlen;
                    let (cpu, p1) = parse_len_string(data, base_pos)?;
                    let (os, _) = parse_len_string(data, p1)?;
                    RecordData::HINFO { cpu, os }
                }
                29 => { // LOC
                    if rdata_bytes.len() < 16 {
                        return Err("invalid LOC record".to_string());
                    }
                    let _version = rdata_bytes[0];
                    let size_raw = rdata_bytes[1];
                    let horiz_raw = rdata_bytes[2];
                    let vert_raw = rdata_bytes[3];
                    let lat_val = u32::from_be_bytes([rdata_bytes[4], rdata_bytes[5], rdata_bytes[6], rdata_bytes[7]]);
                    let lon_val = u32::from_be_bytes([rdata_bytes[8], rdata_bytes[9], rdata_bytes[10], rdata_bytes[11]]);
                    let alt_val = u32::from_be_bytes([rdata_bytes[12], rdata_bytes[13], rdata_bytes[14], rdata_bytes[15]]);

                    let (size, _) = format_loc_precision(size_raw);
                    let (_, horiz_pre) = format_loc_precision(horiz_raw);
                    let (_, vert_pre) = format_loc_precision(vert_raw);

                    let latitude = format_loc_coordinate(lat_val, true);
                    let longitude = format_loc_coordinate(lon_val, false);
                    let alt_meters = (alt_val as i64 - 10000000) / 100;
                    let altitude = format!("{}m", alt_meters);

                    RecordData::LOC { size, horiz_pre, vert_pre, latitude, longitude, altitude }
                }
                41 => { // OPT
                    let payload_size = rclass;
                    let ext_rcode = (ttl >> 24) as u8;
                    let version = ((ttl >> 16) & 0xFF) as u8;
                    let flags = (ttl & 0xFFFF) as u16;
                    RecordData::OPT {
                        payload_size,
                        version,
                        flags,
                        bytes: rdata_bytes,
                    }
                }
                _ => RecordData::Unknown(rdata_bytes),
            };

            recs.push(DnsRecord {
                name,
                rtype,
                rclass,
                ttl,
                data: record_data,
            });
        }
        Ok(recs)
    };

    let answers = parse_record_list(&mut parser, ancount)?;
    let authorities = parse_record_list(&mut parser, nscount)?;
    let additionals = parse_record_list(&mut parser, arcount)?;

    Ok(DnsPacket {
        header,
        questions,
        answers,
        authorities,
        additionals,
    })
}

mod hex {
    pub fn encode(bytes: &[u8]) -> String {
        let mut s = String::with_capacity(bytes.len() * 2);
        for b in bytes {
            s.push_str(&format!("{:02x}", b));
        }
        s
    }
}
EOF"}

