use std::fs;
use std::net::{SocketAddr, ToSocketAddrs};

pub fn get_system_nameservers() -> Result<Vec<String>, String> {
    if let Ok(contents) = fs::read_to_string("/etc/resolv.conf") {
        let mut ns_list = Vec::new();
        for line in contents.lines() {
            let line = line.trim();
            if line.starts_with('#') || line.starts_with(';') {
                continue;
            }
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 && parts[0] == "nameserver" {
                ns_list.push(parts[1].to_string());
            }
        }
        if !ns_list.is_empty() {
            return Ok(ns_list);
        }
    }
    Err("failed to obtain system nameserver information".to_string())
}

pub fn resolve_nameserver_addr(ns: &str, default_port: u16) -> Result<String, String> {
    if ns.starts_with("https://") || ns.starts_with("http://") {
        return Ok(ns.to_string());
    }

    let addr_str = if ns.contains(':') && !ns.starts_with('[') {
        ns.to_string()
    } else {
        format!("{}:{}", ns, default_port)
    };

    if let Ok(mut addrs) = addr_str.to_socket_addrs() {
        if let Some(addr) = addrs.next() {
            return Ok(addr.to_string());
        }
    }

    Err(format!("failed to lookup address information: Name or service not known"))
}
