use std::io::{Read, Write};
use std::net::{SocketAddr, TcpStream, UdpSocket};
use std::os::raw::{c_char, c_int, c_long, c_void};
use std::time::Duration;

use crate::args::TransportType;
use crate::dns_wire::{build_query, parse_packet, DnsPacket};

#[link(name = "ssl")]
#[link(name = "crypto")]
extern "C" {
    fn OPENSSL_init_ssl(opts: u64, settings: *const c_void) -> c_int;
    fn TLS_client_method() -> *const c_void;
    fn SSL_CTX_new(method: *const c_void) -> *mut c_void;
    fn SSL_CTX_free(ctx: *mut c_void);
    fn SSL_new(ctx: *mut c_void) -> *mut c_void;
    fn SSL_free(ssl: *mut c_void);
    fn SSL_set_fd(ssl: *mut c_void, fd: c_int) -> c_int;
    fn SSL_ctrl(ssl: *mut c_void, cmd: c_int, larg: c_long, parg: *mut c_void) -> c_long;
    fn SSL_connect(ssl: *mut c_void) -> c_int;
    fn SSL_write(ssl: *mut c_void, buf: *const c_void, num: c_int) -> c_int;
    fn SSL_read(ssl: *mut c_void, buf: *mut c_void, num: c_int) -> c_int;
}

use std::os::unix::io::AsRawFd;

fn set_sni(ssl: *mut c_void, hostname: &str) {
    if let Ok(c_str) = std::ffi::CString::new(hostname) {
        unsafe {
            SSL_ctrl(ssl, 55, 0, c_str.as_ptr() as *mut c_void);
        }
    }
}

pub fn send_udp(
    addr: &str,
    txid: u16,
    domain: &str,
    qtype: u16,
    qclass: u16,
    edns: bool,
    bufsize: u16,
    aa: bool,
    ad: bool,
    cd: bool,
    allow_fallback: bool,
) -> Result<DnsPacket, String> {
    let sock = UdpSocket::bind("0.0.0.0:0").map_err(|e| format!("{}", e))?;
    sock.set_read_timeout(Some(Duration::from_secs(5))).ok();

    let req_bytes = build_query(txid, domain, qtype, qclass, edns, bufsize, aa, ad, cd);

    let target: SocketAddr = addr.parse().map_err(|e| format!("{}", e))?;
    sock.send_to(&req_bytes, target).map_err(|e| format!("{}", e))?;

    let mut buf = [0u8; 4096];
    let (amt, _) = sock.recv_from(&mut buf).map_err(|e| format!("{}", e))?;

    let packet = parse_packet(&buf[..amt])?;

    if packet.header.is_tc() && allow_fallback {
        return send_tcp(addr, txid, domain, qtype, qclass, edns, bufsize, aa, ad, cd);
    }

    Ok(packet)
}

pub fn send_tcp(
    addr: &str,
    txid: u16,
    domain: &str,
    qtype: u16,
    qclass: u16,
    edns: bool,
    bufsize: u16,
    aa: bool,
    ad: bool,
    cd: bool,
) -> Result<DnsPacket, String> {
    let target: SocketAddr = addr.parse().map_err(|e| format!("{}", e))?;
    let mut stream = TcpStream::connect_timeout(&target, Duration::from_secs(5)).map_err(|e| format!("{}", e))?;
    stream.set_read_timeout(Some(Duration::from_secs(5))).ok();

    let req_bytes = build_query(txid, domain, qtype, qclass, edns, bufsize, aa, ad, cd);
    let len_prefix = (req_bytes.len() as u16).to_be_bytes();

    stream.write_all(&len_prefix).map_err(|e| format!("{}", e))?;
    stream.write_all(&req_bytes).map_err(|e| format!("{}", e))?;

    let mut len_buf = [0u8; 2];
    stream.read_exact(&mut len_buf).map_err(|e| format!("{}", e))?;
    let resp_len = u16::from_be_bytes(len_buf) as usize;

    let mut resp_buf = vec![0u8; resp_len];
    stream.read_exact(&mut resp_buf).map_err(|e| format!("{}", e))?;

    parse_packet(&resp_buf)
}

pub fn send_tls(
    addr: &str,
    txid: u16,
    domain: &str,
    qtype: u16,
    qclass: u16,
    edns: bool,
    bufsize: u16,
    aa: bool,
    ad: bool,
    cd: bool,
) -> Result<DnsPacket, String> {
    let target: SocketAddr = addr.parse().map_err(|e| format!("{}", e))?;
    let stream = TcpStream::connect_timeout(&target, Duration::from_secs(5)).map_err(|e| format!("{}", e))?;

    unsafe {
        OPENSSL_init_ssl(0, std::ptr::null());
