                "\x1b[31m"
            } else {
                "\x1b[41;37m"
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Section {
    Answer,
    Authority,
    Additional,
}

pub struct DisplayRow {
    pub type_name: String,
    pub domain_name: String,
    pub ttl_str: String,
    pub section: Section,
    pub data_str: String,
    pub rtype: u16,
}

pub fn print_output(
    opts: &Options,
    packets: &[DnsPacket],
    elapsed: Option<Duration>,
    is_tty: bool,
) -> i32 {
    let use_color = match opts.color {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Automatic => is_tty,
    };

    if opts.short {
        let mut answers_found = Vec::new();
        for pkt in packets {
            for ans in &pkt.answers {
                let data_text = format_record_data_text(&ans.data, opts.seconds);
                answers_found.push(data_text);
            }
        }
        if answers_found.is_empty() {
            eprintln!("No results");
            return 2;
        } else {
            for ans in answers_found {
                println!("{}", ans);
            }
            return 0;
        }
    }

    if opts.json {
        print_json_output(opts, packets, elapsed);
        return 0;
    }

    let mut rows = Vec::new();

    for pkt in packets {
        for ans in &pkt.answers {
            rows.push(DisplayRow {
                type_name: format_record_type_name(ans.rtype),
                domain_name: ans.name.clone(),
                ttl_str: format_duration(ans.ttl, opts.seconds),
                section: Section::Answer,
                data_str: format_record_data_text(&ans.data, opts.seconds),
                rtype: ans.rtype,
            });
        }
        for auth in &pkt.authorities {
            rows.push(DisplayRow {
                type_name: format_record_type_name(auth.rtype),
                domain_name: auth.name.clone(),
                ttl_str: format_duration(auth.ttl, opts.seconds),
                section: Section::Authority,
                data_str: format_record_data_text(&auth.data, opts.seconds),
                rtype: auth.rtype,
            });
        }
        for add in &pkt.additionals {
            if add.rtype == 41 && opts.edns != EdnsSetting::Show {
                continue;
            }
            rows.push(DisplayRow {
                type_name: format_record_type_name(add.rtype),
                domain_name: add.name.clone(),
                ttl_str: format_duration(add.ttl, opts.seconds),
                section: Section::Additional,
                data_str: format_record_data_text(&add.data, opts.seconds),
                rtype: add.rtype,
            });
        }
    }

    if rows.is_empty() {
        if let Some(first_pkt) = packets.first() {
            let rcode = first_pkt.header.rcode();
            if rcode != 0 {
                let status_str = match rcode {
                    1 => "Format Error",
                    2 => "Server Failure",
                    3 => "NXDomain",
                    4 => "Not Implemented",
                    5 => "Query Refused",
                    _ => "Error",
                };
                println!("Status: {}", status_str);
            }
        }
        if opts.time {
            if let Some(dur) = elapsed {
                println!("Ran in {}ms", dur.as_millis());
            }
        }
        return 0;
    }

    let max_type_len = rows.iter().map(|r| r.type_name.len()).max().unwrap_or(0);
    let max_domain_len = rows.iter().map(|r| r.domain_name.len()).max().unwrap_or(0);
    let max_ttl_len = rows.iter().map(|r| r.ttl_str.len()).max().unwrap_or(0);

    for r in &rows {
        let padded_type = format!("{:>width$}", r.type_name, width = max_type_len);
        let padded_domain = format!("{:<width$}", r.domain_name, width = max_domain_len);
        let padded_ttl = format!("{:>width$}", r.ttl_str, width = max_ttl_len);

        let section_symbol = match (r.section, use_color) {
            (Section::Answer, _) => "   ",
            (Section::Authority, true) => " \x1b[36mA\x1b[0m ",
            (Section::Authority, false) => " A ",
            (Section::Additional, true) => " \x1b[32m+\x1b[0m ",
            (Section::Additional, false) => " + ",
        };

        if use_color {
            let type_color = get_type_color_code(r.rtype, r.section == Section::Authority);
            println!(
                "{}{}\x1b[0m \x1b[1;34m{}\x1b[0m {}{}{}",
                type_color, padded_type, padded_domain, padded_ttl, section_symbol, r.data_str
            );
        } else {
            println!(
                "{} {} {}{}{}",
                padded_type, padded_domain, padded_ttl, section_symbol, r.data_str
            );
        }
    }

    if opts.time {
        if let Some(dur) = elapsed {
            println!("Ran in {}ms", dur.as_millis());
        }
    }

    0
}

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out
}

fn record_data_to_json(data: &RecordData) -> String {
    match data {
        RecordData::A(ip) => format!("{{\"address\":\"{}\"}}", ip),
        RecordData::AAAA(ip) => format!("{{\"address\":\"{}\"}}", ip),
        RecordData::CNAME(domain) => format!("{{\"domain\":\"{}\"}}", json_escape(domain)),
        RecordData::PTR(domain) => format!("{{\"cname\":\"{}\"}}", json_escape(domain)),
        RecordData::NS(domain) => format!("{{\"nameserver\":\"{}\"}}", json_escape(domain)),
        RecordData::MX { preference, exchange } => {
            format!("{{\"preference\":{},\"exchange\":\"{}\"}}", preference, json_escape(exchange))
        }
        RecordData::TXT(msgs) => {
            let quoted: Vec<String> = msgs.iter().map(|m| format!("\"{}\"", json_escape(m))).collect();
            format!("{{\"messages\":[{}]}}", quoted.join(","))
        }
        RecordData::SOA { mname, .. } => format!("{{\"mname\":\"{}\"}}", json_escape(mname)),
        RecordData::SRV {
            priority,
            weight,
            port,
            target,
        } => {
            format!(
                "{{\"priority\":{},\"weight\":{},\"port\":{},\"target\":\"{}\"}}",
                priority, weight, port, json_escape(target)
            )
        }
        RecordData::CAA {
            critical,
            tag,
            value,
        } => {
            format!(
                "{{\"critical\":{},\"tag\":\"{}\",\"value\":\"{}\"}}",
                critical, json_escape(tag), json_escape(value)
            )
        }
        RecordData::NAPTR {
            order,
            preference,
            flags,
            service,
            regex,
            replacement,
        } => {
            format!(
                "{{\"order\":{},\"preference\":{},\"flags\":\"{}\",\"service\":\"{}\",\"regex\":\"{}\",\"replacement\":\"{}\"}}",
                order, preference, json_escape(flags), json_escape(service), json_escape(regex), json_escape(replacement)
            )
        }
        RecordData::TLSA {
            certificate_usage,
            selector,
            matching_type,
            certificate_data,
        } => {
            format!(
                "{{\"certificate_usage\":{},\"selector\":{},\"matching_type\":{},\"certificate_data\":\"{}\"}}",
                certificate_usage, selector, matching_type, json_escape(certificate_data)
            )
        }
        RecordData::SSHFP {
            algorithm,
            fingerprint_type,
            fingerprint,
        } => {
            format!(
                "{{\"algorithm\":{},\"fingerprint_type\":{},\"fingerprint\":\"{}\"}}",
                algorithm, fingerprint_type, json_escape(fingerprint)
            )
        }
        RecordData::HINFO { cpu, os } => format!("{{\"cpu\":\"{}\",\"os\":\"{}\"}}", json_escape(cpu), json_escape(os)),
        RecordData::LOC {
            size,
            horiz_pre,
            vert_pre,
            latitude,
            longitude,
            altitude,
        } => {
            format!(
                "{{\"size\":\"{}\",\"precision\":{{\"horizontal\":{},\"vertical\":{}}},\"point\":{{\"latitude\":\"{}\",\"longitude\":\"{}\",\"altitude\":\"{}\"}}}}",
                json_escape(size), horiz_pre, vert_pre, json_escape(latitude), json_escape(longitude), json_escape(altitude)
            )
        }
        RecordData::OPT { version, .. } => format!("{{\"version\":{},\"data\":[]}}", version),
        RecordData::Unknown(bytes) => {
            let strs: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
            format!("{{\"bytes\":[{}]}}", strs.join(","))
        }
    }
}

fn record_to_json(rec: &DnsRecord) -> String {
    let type_json = if let Some(tstr) = type_num_to_str(rec.rtype) {
        format!("\"{}\"", tstr)
    } else {
        rec.rtype.to_string()
    };

    format!(
        "{{\"name\":\"{}\",\"class\":\"{}\",\"ttl\":{},\"type\":{},\"data\":{}}}",
        json_escape(&rec.name),
        class_num_to_str(rec.rclass),
        rec.ttl,
        type_json,
        record_data_to_json(&rec.data)
    )
}

pub fn print_json_output(opts: &Options, packets: &[DnsPacket], elapsed: Option<Duration>) {
    let mut resp_jsons = Vec::new();

    for pkt in packets {
        let mut q_jsons = Vec::new();
        for q in &pkt.questions {
            let type_json = if let Some(tstr) = type_num_to_str(q.qtype) {
                format!("\"{}\"", tstr)
            } else {
                q.qtype.to_string()
            };
            q_jsons.push(format!(
                "{{\"name\":\"{}\",\"class\":\"{}\",\"type\":{}}}",
                json_escape(&q.name),
                class_num_to_str(q.qclass),
                type_json
            ));
        }

        let ans_jsons: Vec<String> = pkt.answers.iter().map(record_to_json).collect();
        let auth_jsons: Vec<String> = pkt.authorities.iter().map(record_to_json).collect();
        let add_jsons: Vec<String> = pkt
            .additionals
            .iter()
            .filter(|a| a.rtype != 41 || opts.edns == EdnsSetting::Show)
            .map(record_to_json)
            .collect();

        resp_jsons.push(format!(
            "{{\"queries\":[{}],\"answers\":[{}],\"authorities\":[{}],\"additionals\":[{}]}}",
            q_jsons.join(","),
            ans_jsons.join(","),
            auth_jsons.join(","),
            add_jsons.join(",")
        ));
    }

    let mut json_out = format!("{{\"responses\":[{}]", resp_jsons.join(","));

    if opts.time {
        if let Some(dur) = elapsed {
            json_out.push_str(&format!(
                ",\"duration\":{{\"secs\":{},\"millis\":{}}}",
                dur.as_secs(),
                dur.subsec_millis()
            ));
        }
    }

    json_out.push('}');
    println!("{}", json_out);
}
EOF"}

