fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out
}

fn record_data_to_json(data: &RecordData) -> String {
    match data {
        RecordData::A(ip) => format!("{{\"address\":\"{}\"}}", ip),
        RecordData::AAAA(ip) => format!("{{\"address\":\"{}\"}}", ip),
        RecordData::CNAME(domain) => format!("{{\"domain\":\"{}\"}}", json_escape(domain)),
        RecordData::PTR(domain) => format!("{{\"cname\":\"{}\"}}", json_escape(domain)),
        RecordData::NS(domain) => format!("{{\"nameserver\":\"{}\"}}", json_escape(domain)),
        RecordData::MX { preference, exchange } => {
            format!("{{\"preference\":{},\"exchange\":\"{}\"}}", preference, json_escape(exchange))
        }
        RecordData::TXT(msgs) => {
            let quoted: Vec<String> = msgs.iter().map(|m| format!("\"{}\"", json_escape(m))).collect();
            format!("{{\"messages\":[{}]}}", quoted.join(","))
        }
        RecordData::SOA { mname, .. } => format!("{{\"mname\":\"{}\"}}", json_escape(mname)),
        RecordData::SRV {
            priority,
            weight,
            port,
            target,
        } => {
            format!(
                "{{\"priority\":{},\"weight\":{},\"port\":{},\"target\":\"{}\"}}",
                priority, weight, port, json_escape(target)
            )
        }
        RecordData::CAA {
            critical,
            tag,
            value,
        } => {
            format!(
                "{{\"critical\":{},\"tag\":\"{}\",\"value\":\"{}\"}}",
                critical, json_escape(tag), json_escape(value)
            )
        }
        RecordData::NAPTR {
            order,
            preference,
            flags,
            service,
            regex,
            replacement,
        } => {
            format!(
                "{{\"order\":{},\"preference\":{},\"flags\":\"{}\",\"service\":\"{}\",\"regex\":\"{}\",\"replacement\":\"{}\"}}",
                order, preference, json_escape(flags), json_escape(service), json_escape(regex), json_escape(replacement)
            )
        }
        RecordData::TLSA {
            certificate_usage,
            selector,
            matching_type,
            certificate_data,
        } => {
            format!(
                "{{\"certificate_usage\":{},\"selector\":{},\"matching_type\":{},\"certificate_data\":\"{}\"}}",
                certificate_usage, selector, matching_type, json_escape(certificate_data)
            )
        }
        RecordData::SSHFP {
            algorithm,
            fingerprint_type,
            fingerprint,
        } => {
            format!(
                "{{\"algorithm\":{},\"fingerprint_type\":{},\"fingerprint\":\"{}\"}}",
                algorithm, fingerprint_type, json_escape(fingerprint)
            )
        }
        RecordData::HINFO { cpu, os } => format!("{{\"cpu\":\"{}\",\"os\":\"{}\"}}", json_escape(cpu), json_escape(os)),
        RecordData::LOC {
            size,
            horiz_pre,
            vert_pre,
            latitude,
            longitude,
            altitude,
        } => {
            format!(
                "{{\"size\":\"{}\",\"precision\":{{\"horizontal\":{},\"vertical\":{}}},\"point\":{{\"latitude\":\"{}\",\"longitude\":\"{}\",\"altitude\":\"{}\"}}}}",
                json_escape(size), horiz_pre, vert_pre, json_escape(latitude), json_escape(longitude), json_escape(altitude)
            )
        }
        RecordData::OPT { version, .. } => format!("{{\"version\":{},\"data\":[]}}", version),
        RecordData::Unknown(bytes) => {
            let strs: Vec<String> = bytes.iter().map(|b| b.to_string()).collect();
            format!("{{\"bytes\":[{}]}}", strs.join(","))
        }
    }
}

fn record_to_json(rec: &DnsRecord) -> String {
    let type_json = if let Some(tstr) = type_num_to_str(rec.rtype) {
        format!("\"{}\"", tstr)
    } else {
        rec.rtype.to_string()
    };

    format!(
        "{{\"name\":\"{}\",\"class\":\"{}\",\"ttl\":{},\"type\":{},\"data\":{}}}",
        json_escape(&rec.name),
        class_num_to_str(rec.rclass),
