pub fn get_type_color_code(rtype: u16, is_authority: bool) -> &'static str {
    if is_authority {
        return "\x1b[31m";
    }
    match rtype {
        1 | 28 => "\x1b[1;32m", // A, AAAA
        5 | 16 | 13 | 52 | 29 => "\x1b[33m", // CNAME, TXT, HINFO, TLSA, LOC
        15 | 33 | 44 => "\x1b[36m", // MX, SRV, SSHFP
        2 | 12 | 257 | 35 => "\x1b[31m", // NS, PTR, CAA, NAPTR
        6 => "\x1b[35m", // SOA
        _ => {
            if type_num_to_str(rtype).is_some() {
                "\x1b[31m"
            } else {
                "\x1b[41;37m"
            }
        }
    }
