        if ret <= 0 {
            SSL_free(ssl);
            SSL_CTX_free(ctx);
            return Err("TLS handshake failed".to_string());
        }

        let req_bytes = build_query(txid, domain, qtype, qclass, edns, bufsize, aa, ad, cd);

        let http_req = format!(
            "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Type: application/dns-message\r\nAccept: application/dns-message\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
            path, host, req_bytes.len()
        );

        SSL_write(ssl, http_req.as_ptr() as *const c_void, http_req.len() as c_int);
        SSL_write(ssl, req_bytes.as_ptr() as *const c_void, req_bytes.len() as c_int);

        let mut resp_data = Vec::new();
        let mut buf = [0u8; 1024];
        loop {
            let r = SSL_read(ssl, buf.as_mut_ptr() as *mut c_void, 1024);
            if r <= 0 {
                break;
            }
            resp_data.extend_from_slice(&buf[..r as usize]);
        }

        SSL_free(ssl);
        SSL_CTX_free(ctx);

        if let Some(body_start) = resp_data.windows(4).position(|w| w == b"\r\n\r\n") {
            let dns_body = &resp_data[body_start + 4..];
            parse_packet(dns_body)
        } else {
            Err("Invalid HTTP response".to_string())
        }
    }
}
EOF"}

