                                        &resolved_ns,
                                        txid,
                                        domain,
                                        qtype,
                                        qclass,
                                        send_edns,
                                        bufsize,
                                        opts.tweaks.aa,
                                        opts.tweaks.ad,
                                        opts.tweaks.cd,
                                        allow_udp_fallback,
                                    ),
                                    TransportType::Tcp => send_tcp(
                                        &resolved_ns,
                                        txid,
                                        domain,
                                        qtype,
                                        qclass,
                                        send_edns,
                                        bufsize,
                                        opts.tweaks.aa,
                                        opts.tweaks.ad,
                                        opts.tweaks.cd,
                                    ),
                                    TransportType::Tls => send_tls(
                                        &resolved_ns,
                                        txid,
                                        domain,
                                        qtype,
                                        qclass,
                                        send_edns,
                                        bufsize,
                                        opts.tweaks.aa,
                                        opts.tweaks.ad,
                                        opts.tweaks.cd,
                                    ),
                                    TransportType::Https => send_https(
                                        &resolved_ns,
                                        txid,
                                        domain,
                                        qtype,
                                        qclass,
                                        send_edns,
                                        bufsize,
                                        opts.tweaks.aa,
                                        opts.tweaks.ad,
                                        opts.tweaks.cd,
                                    ),
                                };

                                match pkt_res {
                                    Ok(pkt) => packets.push(pkt),
                                    Err(e) => {
                                        if opts.json {
                                            println!("{{\"responses\":[]}}");
                                            eprintln!("{{\"error\":true,\"error_phase\":\"network\",\"error_message\":\"{}\"}}", e);
                                        } else {
                                            eprintln!("Error [network]: {}", e);
                                        }
                                        std::process::exit(1);
                                    }
                                }
                            }
                        }
                    }
                }
            }

            let elapsed = if opts.time {
                Some(start_time.elapsed())
            } else {
                None
            };

            let exit_code = print_output(&opts, &packets, elapsed, is_tty);
            std::process::exit(exit_code);
        }
    }
}

fn atty_check() -> bool {
    unsafe {
        isatty(1) != 0
    }
}

fn rand_u16() -> u16 {
    use std::collections::hash_map::RandomState;
    use std::hash::{BuildHasher, Hasher};
    let s = RandomState::new();
    let mut h = s.build_hasher();
    h.write_u128(std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos());
    h.finish() as u16
}
